<div class="top"><h1>Commandes <small class="muted">(<?= (int) $total ?>)</small></h1></div>
<form class="filters-bar" method="get"><input name="q" placeholder="Réf., nom, e-mail, téléphone" value="<?= e(get('q')) ?>"><select name="status"><option value="">Tous les statuts</option><?= select_opts(array_map(fn($s) => $s[0], ORDER_STATUS), get('status')) ?></select><select name="pay"><option value="">Tout paiement</option><?= select_opts(['pending' => 'En attente', 'declared' => 'Déclaré (à vérifier)', 'paid' => 'Payé', 'refunded' => 'Remboursé'], get('pay')) ?></select><button class="btn btn-p btn-sm">Filtrer</button></form>
<div class="tbl-wrap"><table class="tbl"><thead><tr><th>N°</th><th>Date</th><th>Client</th><th>Statut</th><th>Paiement</th><th class="right">Total</th></tr></thead><tbody>
<?php foreach ($rows as $o): ?><tr><td><a href="/admin/commandes/<?= (int) $o['id'] ?>"><b><?= e($o['ref']) ?></b></a></td><td><?= fdate($o['created_at'], true) ?></td><td><?= e($o['name']) ?><br><small class="muted"><?= e($o['phone']) ?></small></td><td><?= status_badge(ORDER_STATUS, $o['status']) ?></td><td><?= $o['payment_status'] === 'declared' ? '<span class="badge b-warn">À vérifier</span>' : ($o['payment_status'] === 'paid' ? '<span class="badge b-ok">Payé</span>' : '<span class="badge b-info">' . ['pending' => 'En attente', 'refunded' => 'Remboursé'][$o['payment_status']] . '</span>') ?></td><td class="right"><?= money($o['total']) ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="6" class="center muted">Aucune commande.</td></tr><?php endif; ?></tbody></table></div>
<?php if ($pages > 1): ?><nav class="pager"><?php for ($i = 1; $i <= $pages; $i++): ?><?= $i === $pg ? '<span class="on">' . $i . '</span>' : '<a href="' . e(qs(['page' => $i])) . '">' . $i . '</a>' ?><?php endfor; ?></nav><?php endif; ?>
